//@name serial_gradation_agents_for_rp
//@display-name GRADIA
//@api 3.0
//@version 0.23.2
//@update-url https://raw.githubusercontent.com/rusinus12-droid/GRADIA/main/GRADIA.js
//@arg mode string off|lite|normal
//@arg multi_pipeline_mode string lightweight|heavyweight — lightweight combines analysis and drafting in one call per stage; heavyweight separates them
//@arg turn_window int Legacy global recent-turn fallback; migrated once into each stage slot
//@arg max_recent_chars int Legacy global context fallback; migrated once into each stage slot
//@arg max_previous_stage_chars int Maximum latest same-turn draft characters available to the next serial AIDE
//@arg max_injection_chars int Maximum final draft characters injected into the main request
//@arg gradation_mode string full_draft — SHADOW ACT writes the first full draft and serial AIDEs revise the latest full draft
//@arg output_mode string draft_guided|risu_engine — draft_guided is 기본 모드, risu_engine is 확장 모드
//@arg built_in_style_preset string unified_stylepack
//@arg injection_position string first_system|last_system|before_last_user
//@arg failure_mode string soft|degraded|hard
//@arg stage_timeout_ms int Legacy global timeout fallback; migrated once into each stage slot
//@arg model_presets_json string JSON object of saved model presets
//@arg provider_presets_json string LIBRA/RE-compatible alias for model_presets_json
//@arg provider_presets_risuai_enabled string Reserved LIBRA-compatible flag: true|false
//@arg default_preset string Default model preset name
//@arg shadow_act_preset string Model preset for SHADOW ACT
//@arg character_aide_preset string Model preset for Character AIDE
//@arg world_aide_preset string Model preset for World AIDE
//@arg plot_aide_preset string Model preset for Plot AIDE
//@arg input_assist_preset string Optional model preset for the top-level Input Writing Assistant
//@arg user_intent_ooc_preset string Optional model preset for the target-selectable Creative Direction OOC
//@arg input_assist_mode string off|user_focus|npc_focus|offscreen_focus|random
//@arg input_assist_scope string full_pipeline|standalone
//@arg input_assist_target_chars string 300|500|800|1000|omakase
//@arg input_assist_confirmation_mode string direct|confirm
//@arg input_assist_always_translate_english string true|false
//@arg information_transfer_mode string draft_only|draft_and_analysis
//@arg selected_module_lore_ids string JSON/comma-separated IDs or namespaces of module lorebooks GRADIA may read
//@arg aide_stage_order string JSON/comma-separated order for Character, World, Plot AIDE; SHADOW ACT is always first
//@arg llm_provider string Fallback main LLM provider
//@arg llm_url string Fallback main LLM URL
//@arg llm_key string Fallback main LLM API key / Vertex bearer token / JSON placeholder
//@arg llm_model string Fallback main LLM model
//@arg llm_temp string Fallback main LLM temperature
//@arg llm_timeout int Fallback main LLM timeout ms
//@arg llm_timeout_ms int RE-compatible fallback timeout alias
//@arg llm_max_completion_tokens int Fallback main LLM max completion tokens
//@arg llm_request_format string Fallback request format: chat_completions|responses
//@arg llm_reasoning_preset string Fallback reasoning preset: auto|off|gpt|openrouter|gemini|gemini_budget|claude|claude_budget|deepseek|kimi|glm|ollama|custom
//@arg llm_reasoning_effort string Fallback reasoning effort: none|minimal|low|medium|high|xhigh|max
//@arg llm_reasoning_budget_tokens int Fallback reasoning budget tokens (-1 enables dynamic Gemini budget)
//@arg llm_thinking_type string Fallback thinking toggle: enabled|disabled
//@arg llm_glm_thinking_type string Backward-compatible GLM thinking type alias
//@arg llm_glm_thinking string Fallback GLM thinking alias
//@arg llm_service_tier string Fallback service tier: off|auto|default|flex|priority|scale
//@arg custom_service_tier_passthrough string LIBRA-compatible custom provider service_tier passthrough: true|false
//@arg vertex_flex_mode string LIBRA-compatible Vertex Flex mode: off|provisioned_then_flex|flex_only
//@arg llm_stream string Fallback stream flag: true|false
//@arg enable_shadow_act string true|false
//@arg enable_character_aide string true|false
//@arg enable_world_aide string true|false
//@arg enable_plot_aide string true|false
//@arg shadow_prompt_extra string Legacy SHADOW ACT addendum; automatically merged into the user creative instruction
//@arg character_prompt_extra string Legacy Character AIDE addendum; automatically merged into the user creative instruction
//@arg world_prompt_extra string Legacy World AIDE addendum; automatically merged into the user creative instruction
//@arg plot_prompt_extra string Legacy Plot AIDE addendum; automatically merged into the user creative instruction
//@arg shadow_prompt_mode string builtin|replace — legacy replace means direction guidance enabled, not prompt replacement
//@arg character_prompt_mode string builtin|replace — legacy replace means direction guidance enabled, not prompt replacement
//@arg world_prompt_mode string builtin|replace — legacy replace means direction guidance enabled, not prompt replacement
//@arg plot_prompt_mode string builtin|replace — legacy replace means direction guidance enabled, not prompt replacement
//@arg shadow_prompt_custom string SHADOW ACT creative instruction for analysis and writing; built-in structure is always preserved
//@arg character_prompt_custom string Character AIDE creative instruction for analysis and writing; built-in structure is always preserved
//@arg world_prompt_custom string World AIDE creative instruction for analysis and writing; built-in structure is always preserved
//@arg plot_prompt_custom string Plot AIDE creative instruction for analysis and writing; built-in structure is always preserved
//@arg llm_extra_body_json string Fallback extra JSON body merged into provider requests
//@arg debug_log string true|false
//@arg shadow_include_risu_context string Legacy RAG toggle; migrated once into per-stage RisuAI reference switches
//@arg shadow_risu_context_max_chars int Legacy RAG context fallback; migrated once into per-stage context limits
//@arg backend_hosting_mode string Hosting bridge mode: off|auto|hosted
//@arg backend_hosting_url string LIBRA hosting bridge backend URL
//@arg backend_hosting_token string LIBRA hosting bridge backend token
//@arg enable_gui string true|false
/*
 * Serial Gradation Agents for RP v0.23.2
 *
 * A RisuAI API v3 plugin that turns the old RE Companion V2 current-turn
 * Shadow Act/AIDE staging idea into the Serial Gradation Agents for RP
 * drafting and post-response editing pipeline.
 *
 * v0.2.0 adds model preset routing and afterRequest post-processing.
 * v0.12.3 adds request-scoped draft lineage locking, prior-turn regression detection,
 * isolated lineage recovery retries, and authoritative field-first draft parsing.
 * v0.12.23 aligns the plugin more closely with RisuAI API v3 runtime behavior:
 * same-request retries reuse one completed GRADIA injection, legacy arguments are cached,
 * replacer permission is verified explicitly, bridge tokens move to local-only storage,
 * GUI initialization is deferred, and host iframe selection uses exact document ownership.
 * v0.13.2 exposes independent AI connection selection for all four base stages in
 * Easy Settings while preserving the existing per-stage preset routing and fallback.
 *
 * v0.13.1 adds strict module-lore selection: only explicitly selected active modules are
 * traversed for GRADIA private context. It also expands read-only CBS/Lua-state
 * interpretation for lorebooks without executing persistent state-changing macros.
 *
 * v0.14.0 fuses the former User DLC and World Additional agents into one optional User
 * Intent AIDE. Its design can be rebuilt through a chat-scoped OOC conversation while
 * keeping world-expansion material non-canon until the visible response adopts it.
 *
 * v0.14.1 gives the User Intent OOC conversation its own independently selectable AI
 * connection, separate from the User Intent AIDE that runs before SHADOW ACT.
 *
 * v0.14.2 redesigns the module-lore selector as a balanced responsive card grid so module
 * names, metadata, and descriptions use the available width without narrow-column wrapping.
 *
 * v0.14.3 moves each stage's recent-result panel into a full-width responsive row and gives
 * its inner values a wrapping grid, preventing it from overlapping stage controls.
 *
 * v0.14.4 removes the redundant GRADIA brand block from the left sidebar and makes only
 * the navigation region scroll, keeping the plugin status card visible.
 *
 * v0.16.0 rebuilds User Intent OOC as a real chat flow inspired by LIBRA Story Writer OOC:
 * immediate user-message rendering, Enter-to-send, natural-language replies, independent
 * structured intent compilation, resilient partial success, and visible conversation status.
 * v0.16.1 scopes OOC-derived User Intent guidance to SHADOW ACT only. It also normalizes
 * older manual agreements to persistent scope and repairs malformed world-material fields.
 * v0.17.0 replaces the Writer/User Intent control hierarchy with a target-selectable
 * Creative Direction OOC that edits the built-in guidance of any of the four base stages.
 * v0.17.1 removes the non-functional full mode and migrates legacy full values to normal.
 * v0.17.2 gives every Creative Direction OOC target its own scope explanation, valid
 * example instruction, input hint, and example-aware coaching/compilation safeguards.
 * v0.17.3 starts each target OOC explicitly from an OOC Start button, after which the
 * selected stage introduces its role and shows its own example before user input begins.
 * v0.17.4 makes all four persisted creative directions visible together in the OOC
 * screen, including their full stored text and explicit saved/empty state.
 * v0.18.0 separates OOC conversation from creative-direction generation. Conversation
 * no longer saves automatically; the user explicitly compiles and stores an agreement
 * with a dedicated button. It also fixes stale busy state after intermediate GUI renders.
 * v0.18.1 makes every OOC strictly subordinate to its selected stage. Broad user intent
 * is translated into that stage's responsibilities without allocating work to other AIDEs.
 * v0.18.2 adds an explicit transformation contract for each target so the same broad
 * intent becomes current-turn interaction, character logic, world context, or plot motion.
 * v0.18.3 matches Flashback Memory's live-container resolution and transparent document
 * canvas. The host chat remains visible through a light dim layer instead of being replaced
 * by an opaque dark fullscreen surface in PocketRisu/WebView runtimes.
 * v0.18.4 keeps the selected speed/quality profile when independent settings such as AI
 * connections, OOC guidance, prompts, providers, or module lore are edited. Only direct
 * edits to profile-managed execution and context values switch the profile to custom.
 * v0.19.0 makes analysis-before-writing mandatory for SHADOW ACT and all three AIDEs.
 * Legacy single-call stage settings are migrated, empty analysis JSON is retried once,
 * and analysis/rewrite failures remain visible failures instead of silently falling back
 * to a successful-looking plain-text single call.
 * v0.19.1 prevents Ollama context starvation before requests, sends an explicit
 * think:false on no-thinking retries, and keeps the current same-turn draft inside
 * the retained end of fitted AIDE prompts.
 * v0.20.0 adds an independent target-length selector to Easy Settings. Length
 * choices also size draft handoff and final-injection limits without clearing the
 * selected speed/quality profile.
 * v0.21.0 adds a top-level Input Writing Assistant with user, present-NPC,
 * offscreen-faction, and random modes. It can feed the full draft pipeline or run
 * alone, while Information Transfer independently controls whether private analysis
 * material accompanies the final draft to the main response model.
 * v0.21.1 places the Input Writing Assistant's independent LLM profile selector
 * directly inside its Easy Settings section and separates the four draft-stage
 * profile controls below it.
 * v0.21.2 changes input assistance from source-preserving expansion to semantic
 * reconstruction. It keeps explicit intent and commitments while allowing full
 * rephrasing and reordering, and retries once when a model merely repeats the source.
 * v0.21.3 gives the Input Writing Assistant an independent three-turn default,
 * selectable 300/500/800/1000/omakase reconstruction targets, and visible trace
 * metadata confirming which RisuAI persona, character, and lore references were used.
 * v0.21.4 exposes Information Transfer in Easy Settings and adds a dedicated,
 * directly accessible desktop/mobile sidebar page for its delivery scope.
 * v0.21.5 automatically bypasses Input Writing Assistance when the current U
 * already exists as the latest stored user turn, covering reroll and rollback
 * generation without reconstructing the same user input a second time.
 * v0.21.6 changes lore activation to current-input-first retrieval. Recent
 * conversation can only continue lore that was active in the preceding run,
 * while always-active and recursive lore retain their documented behavior.
 * v0.21.7 directs the downstream main response model to use the GRADIA draft
 * as a same-scene seed and integrate relevant established context without
 * exposing or naming its source.
 * v0.21.8 unifies each draft stage's user creative instruction, migrates the
 * legacy direction addendum into it, and applies the same stage-scoped policy
 * to both mandatory analysis and draft writing. Creative Direction OOC now
 * compiles paired analysis criteria and observable draft behavior.
 * v0.21.9 repairs invalid model-generated JSON string escapes during structured
 * parsing and retries Creative Direction OOC compilation once with a stricter
 * raw-JSON contract before reporting a generation or save failure.
 * v0.21.10 preserves open disclosure panels, scroll positions, focused controls,
 * and text selections across settings GUI rerenders, so editing Expert Settings
 * no longer collapses the page around the changed control.
 * v0.21.11 promotes the immediately preceding completed U+A turn to a dedicated
 * Input Writing Assistant continuity anchor. Older recent turns and lore remain
 * secondary references, preventing reconstructed input from resetting the scene.
 * v0.21.12 locks the original input's actor, target, action, and explicit entity
 * anchors during reconstruction. Blank input, *says nothing*, and explicit scene
 * continuation cues now generate a context-grounded next input from recent turns.
 * v0.21.13 replaces the obsolete 1200-token analysis limit with stage-sized
 * budgets up to 4096 tokens, uses native Ollama JSON output for mandatory
 * analysis, and makes invalid-JSON retries request a bounded compact contract.
 * v0.21.14 makes the final RP draft the dominant downstream artifact. It blocks
 * stale fallback analysis from final transfer, adds visible-scene and current-run
 * hard anchors, preserves stage-scoped creative constraints, and validates
 * actor/action/target continuity before same-scene expansion.
 * v0.21.15 restores the concise draft-preserving handoff philosophy of v0.12.23
 * while retaining current-run safety. At least 80% of final injection capacity is
 * reserved for the draft, and the downstream model is asked to polish lightly,
 * repairing or developing only what the supplied evidence actually requires.
 * v0.21.16 describes continuity evidence by authority and availability rather
 * than naming specific memory plugins. Every stage now treats all relevant context
 * already supplied for the current request as evidence without assuming its source.
 * v0.21.17 removes integration-awareness and fourth-wall wording from narrative
 * drafting and finalization prompts. Context is described only as established scene,
 * character, setting, recent-event, and continuity information.
 * v0.21.18 intercepts blank-send continuation requests at beforeRequest when RisuAI
 * bypasses editinput. It reconstructs the input once, rewrites the outbound user turn,
 * and safely mirrors the replacement into the visible current chat when possible.
 * v0.21.19 detects RisuAI's blank-send placeholder from the actual outbound request
 * before consulting optional chat-index APIs. Host chat access is now used only to
 * enrich continuity and mirror the rewritten turn, so API exposure differences cannot
 * prevent the request itself from being intercepted.
 * v0.21.20 retires the unreliable beforeRequest blank-input interception path.
 * A dedicated chat-menu action now creates a continuation input first and then sends
 * that completed text through RisuAI's official sendChat API.
 * v0.21.21 adds a real send-cancel control to the continuation status panel.
 * Cancellation remains available while the input is being generated and during a
 * short pre-send grace period, and it prevents sendChat from being called.
 * v0.21.22 separates the latest visible endpoint and compact physical-state ledger
 * from private memory packets, validates generated continuation inputs against that
 * terminal state, and prevents visible planning/thought blocks in the final response.
 * v0.21.23 captures the exact latest completed response for the continuation button,
 * preventing a not-yet-persisted chat snapshot from selecting the preceding scene.
 * Terminal lifecycle facts and mandatory validator checks now block completed-action
 * replay and ended-contact revival instead of trusting a bare boolean verdict.
 * v0.21.24 preserves foreign post-processing payloads in the host chat while removing
 * LBDATA/lb-lazy blocks only from GRADIA's private recent-chat reading copies.
 * v0.21.25 removes all foreign-module-specific packet parsing, state extraction,
 * prompt classification, and transport diagnostics. Scene continuity now comes only
 * from visible recent-chat prose; outbound source messages remain generically
 * byte-for-byte preserved without inspecting another module's data format.
 * v0.21.26 fixes the continuation send-cancel panel for RisuAI's document-scoped
 * SafeElement event bridge. Only clicks inside the current cancel button are
 * accepted, and each panel replacement removes its previous listener so stale
 * handlers cannot cancel later continuation requests.
 * v0.21.27 rejects Input Writing Assistant results that stop on a provider
 * length limit, end mid-sentence, or fall drastically below the selected target.
 * One no-thinking retry receives a larger output budget; a second incomplete
 * result fails closed instead of being sent into the draft pipeline.
 * v0.21.28 makes the easy speed/quality profiles materially different. Profiles
 * now scale each stage's analysis token budget and analysis depth while the
 * separate pipeline mode remains responsible for which stages and calls run.
 * Applying a profile no longer resets the selected pipeline mode, and the easy
 * settings cards show their actual context and analysis differences.
 * v0.21.29 shows the same chat-panel work guidance for ordinary user inputs.
 * The panel follows input reconstruction, per-stage analysis and draft work,
 * final response generation, completion, bypass, and failure without exposing
 * a false cancel control after a normal message has already been sent.
 * v0.21.30 ports Hayaku's strengthened weighted-Jaccard retrieval principles
 * into GRADIA's active-lore reader. Long lore is now split into Markdown-aware
 * sections and ranked against the current input before character/persona context
 * packing, with fuzzy token, character n-gram, structural synopsis, and Hangul
 * loanword romanization support for matches such as 루미나 ↔ LUMINA. A strong
 * current-input match can also promote the containing lore prompt for this turn,
 * while forced deactivation, exclusion keys, and selective conditions remain intact.
 * v0.21.31 adds request-local scene, cast, and event attribution ledgers shared by
 * input reconstruction and all draft stages. Explicit scene boundaries demote the
 * previous turn to completed history, and a deterministic guard rejects attempts
 * to transfer that history to newly introduced people. Lore section ranking now
 * combines weighted Jaccard, BM25F-style sparse scoring, and exact entity anchors;
 * inactive lore promotion requires explicit identity evidence. Input target length
 * is a soft preference so valid concise results no longer retry into padded fiction.
 * v0.21.32 makes the original current input authoritative from lore activation
 * onward, merges Korean/English loanword aliases such as 루미나 and LUMINA for
 * scene-cast detection, and excludes asset/command/catalog metadata from participant
 * ledgers. The ledger is injected once, unsupported cross-scene information routes
 * are rejected, and repeated recent-response/RAG material is compacted before model
 * context fitting.
 * v0.21.33 locks both ordinary input reconstruction and explicit continuation to the
 * exact terminal state of the immediate previous completed turn unless the current
 * input explicitly changes time or location. Live response selection rejects stale
 * runtime snapshots already found earlier in stored history, and every locked
 * candidate passes the same post-generation physical-continuity validator.
 * v0.21.34 adds an optional pre-send input review. The original and reconstructed
 * inputs are shown side by side, either version can be selected, and the generated
 * version can be regenerated without leaving the review. Expert Settings chooses
 * between this confirmation flow and the legacy immediate-send behavior. Each side
 * can be translated to English for review or delivery, and an independent expert
 * option automatically translates every reconstructed result before delivery.
 * v0.21.35 moves the input review controls into a dedicated, always-visible
 * "전송 및 확인" card at the top of Input Assist Expert Settings so the review mode
 * and automatic English translation options are no longer buried among generation
 * controls.
 * v0.21.36 keeps the configured recent-N-turn window while separating its authority:
 * only the immediately previous completed U+A turn is supplied as raw scene
 * continuity. Older N-1 turns are reduced to durable relationship, agreement,
 * knowledge, boundary, identity, obligation, and unresolved-goal facts. Their
 * historical locations, physical arrangements, and completed scene actions are no
 * longer supplied as reusable current-scene prose.
 * v0.21.37 routes failed input reconstruction through the same delivery policy as a
 * successful result. The original-input fallback is automatically translated when
 * requested and is held for the side-by-side confirmation dialog when review mode
 * is enabled instead of being sent immediately.
 * v0.21.38 removes third-party product attribution from the Input Assist settings
 * description so acknowledgements can remain on the separate introduction page.
 * v0.21.39 keeps the Input Assist sidebar label on one balanced line in narrow
 * desktop sidebars without changing the mobile horizontal navigation behavior.
 * v0.21.40 renders creative-instruction saved-count indicators as compact,
 * non-wrapping capsules instead of stretched multi-line pills.
 * v0.21.41 redesigns the Easy Settings summary footer with a stable action column,
 * full-width non-wrapping buttons, and a separate readable AI-profile line.
 * v0.21.42 removes the LLM continuity validator as a blocking Input Assist gate.
 * Immediate-turn priority remains in the reconstruction prompt, while generated
 * candidates proceed to the optional user confirmation instead of failing on a
 * second model's interpretation of scene continuity.
 * v0.21.43 makes the immediate previous completed turn the sole current-scene
 * authority for both ordinary input reconstruction and explicit continuation.
 * Older N-1 turns and lore remain background-only, ambiguous transient narration
 * is no longer promoted as a durable fact, and terminal evidence is placed last.
 * v0.21.44 removes protected-anchor and event-attribution validation as blocking
 * Input Assist gates. Their diagnostics remain visible for debugging, but a complete,
 * changed reconstruction now proceeds instead of falling back to the original input.
 * v0.21.45 simplifies Input Assist around one authoritative generation packet:
 * current intent, background-only canon, the immediate completed turn, and its
 * terminal state. Protected-anchor and event-ledger diagnostics are removed from
 * runtime generation, while technical completeness and vague-cue retries remain.
 * v0.22.0 keeps SHADOW ACT as the analysis-first full-draft author and converts the
 * three downstream AIDEs into serial paragraph-patch editors. Each AIDE analyzes the
 * latest same-run draft and returns only structural replace/insert/delete operations;
 * GRADIA applies them locally before handing the revised draft to the next AIDE.
 * Draft regeneration falls from four full outputs to one, while adaptive Ollama
 * token-per-character calibration avoids discarding most of a usable context window.
 * v0.22.1 fixes both ordinary Input Assist reconstruction and GRADIA continuation to
 * one immediate completed U+A turn. Older recent turns and their derived durable-fact
 * summaries are no longer collected, searched, or sent to the Input Assist model;
 * its former recent-turn setting is removed from Easy and Expert Settings.
 * v0.22.2 makes the expanded-message side of Input Assist confirmation directly
 * editable. Sending and manual translation use the current editor value, edits
 * invalidate stale translations, and regeneration deliberately replaces the editor.
 * v0.22.3 reduces ordinary Input Assist and explicit GRADIA continuation to the same
 * terminal-first path. Only the visible tail of the immediately preceding assistant
 * response is allowed to define the live scene; the preceding user request, earlier
 * portions of a long response, and older turns are excluded from generation context.
 * Character, persona, and activated lore remain bounded consistency references, and
 * Input Assist performs one generation call without an automatic corrective rewrite.
 * v0.22.4 extends the same terminal-first contract to the fixed draft pipeline. SHADOW
 * ACT and all three AIDEs use the final visible 2,400 characters of the immediately
 * preceding assistant response as the live scene, while relevant Hypa summaries form
 * one shared read-only long-term continuity packet for history, relationships,
 * knowledge, promises, and unresolved consequences. Historical memory cannot relocate,
 * restage, or replay the terminal scene.
 * v0.22.5 makes the exact pre-assist user input the sole semantic authority for actor,
 * target, action, modality, and completion state. Input Assist prose is retained only as
 * a subordinate wording candidate, and every drafting path must discard candidate
 * clauses that conflict with the original instead of blending the two instructions.
 * v0.22.6 limits that original-fidelity contract to Input Assist generation itself.
 * Once RisuAI submits the reconstructed text, that submitted text becomes the sole
 * current user input for SHADOW ACT, every AIDE, lore retrieval, lineage, expansion
 * mode, and finalization. The superseded pre-assist text remains diagnostic history
 * only and is never injected downstream as a competing instruction.
 * v0.22.7 converts the requested draft-length range into a SHADOW ACT working
 * target and minimum count of distinct scene beats. The analysis call must plan
 * those beats before drafting, and the writing call realizes them inside the same
 * scene without padding or advancing into a sequel. The full-draft JSON contract
 * now carries the prose once instead of duplicating it in response_draft and
 * draft.rp_text.
 * v0.22.8 ports LIBRA Alpha's Story Author / Director responsibility split into
 * SHADOW ACT's existing private analysis call without adding another agent or LLM
 * request. Story Author planning owns scene purpose, tension, causally ordered
 * beats, open questions, payoff candidates, and do-not-resolve boundaries; the
 * Director brief translates that meaning into required outcomes, forbidden moves,
 * continuity locks, staging, dialogue rhythm, and an open ending. Both plans are
 * realized in the SHADOW ACT draft, shown in execution results, and passed to the
 * three serial AIDEs as read-only current-run design constraints. They are never
 * persisted as a competing long-term story database or separately re-injected
 * after the final draft.
 * v0.22.9 makes request-scoped no-thinking analysis effective across every
 * provider family, including OpenAI-compatible LLM Gateway routes. Mandatory
 * analysis now sends the gateway's explicit reasoning-off field and retries
 * malformed or truncated JSON with a larger visible-output allowance, so
 * hidden reasoning cannot consume nearly the entire analysis completion.
 * v0.23.0 divides the serial draft workflow into two explicit multi-pipeline
 * modes. Lightweight mode lets SHADOW ACT and every AIDE perform their own
 * scene judgment and writing in one model call without requiring a separate
 * analysis artifact. Heavyweight mode runs a dedicated structured analysis
 * call followed by a separate full draft or rewrite call for every active
 * stage. Stage count, speed/quality profile, provider selection, creative
 * direction, lore retrieval, and final information transfer remain independent.
 * v0.23.1 hardens provider interoperability without changing credential exposure
 * behavior. Provider stop reasons now survive normal and streamed responses; native
 * JSON modes are applied where supported; unsupported native JSON and thinking
 * controls retry without the rejected field. Gemini 3 and 2.5 Pro use compatible
 * thinking controls, Vertex Flex headers are honored, service tiers are restricted
 * to explicit support, connection tests avoid tiny reasoning-starved completions,
 * model-list caches distinguish credentials, response bodies are consumed once,
 * and namespaced GPT model IDs receive the correct completion-token field.
 * v0.23.2 adds first-class current-model compatibility. GPT-5.6 model IDs and
 * xhigh/max reasoning work through Chat Completions and Responses; Gemini 3.5/3.6
 * use minimal-to-high thinking levels while deprecated sampling fields are removed;
 * Claude Opus 5 supports the full effort ladder and its thinking constraints; and
 * Kimi K3 gains a direct Moonshot provider with its always-on low/high/max reasoning
 * contract. Official model catalogs and quick selections cover all four families.
 *
 * v0.15.1 keeps the RisuAI plugin iframe fullscreen and centers only the GRADIA card,
 * preventing the host container's black background from appearing as a large outer margin.
 * v0.15.0 adds a dedicated portrait mobile GUI for narrow windows: compact top controls,
 * mobile-only navigation, single-column content, and touch-sized controls.
 *
 * v0.12.16 redesigns the visible settings around plain-language choices, guided
 * presets, conversation scope, review priority, and one-click saving while keeping
 * internal numeric controls inside an expert-only section.
 *
 * v0.12.5 upgrades Character, World, and Plot analysis prompts using MARP-inspired
 * source-material isolation, fixed domain checklists, stage-specific JSON notes, and
 * concrete rewrite directives adapted to SGA's same-turn serial rewrite contract.
 * v0.12.7 keeps SHADOW ACT fixed first while allowing Character, World, and Plot
 * AIDE stages to be reordered. The selected order controls GUI layout, provider calls,
 * accumulated analysis inheritance, trace summaries, import/export, and final handoff.
 * v0.12.8 restores the provider editor helpers removed during the Core Only cleanup,
 * prevents blank-screen tab failures with a render error boundary, and presents the GUI
 * as a smaller centered settings window instead of a full-screen dashboard surface.
 * v0.12.9 integrates Living Canon 1.0-inspired authority and continuity contracts:
 * raw current context outranks agent notes, omissions are not prohibitions, knowledge needs
 * a valid in-world path, older scenes require a present bridge, last-known is not current,
 * no-replay and commit barriers prevent stale-scene reuse and premature state application.
 * v0.12.14 changes only the public-facing brand to GRADIA. The internal code name,
 * storage keys, schemas, exported configuration kinds, and compatibility globals remain
 * Serial_Gradation_Agents_for_RP so existing installations and saved settings continue to work.
 * v0.12.15 keeps the documented fullscreen iframe entry point but, after one-time
 * mainDom permission, resizes the plugin host iframe itself into a centered GRADIA panel.
 * The surrounding RisuAI interface remains visible and interactive instead of being covered
 * by a full-viewport transparent iframe. If permission is unavailable, the prior centered
 * transparent fallback remains active.
 * v0.12.18 requests mainDom permission before the fullscreen iframe is shown, so the
 * RisuAI permission confirmation remains unobstructed. After permission is granted, the
 * GRADIA title bar can drag the host iframe, and double-clicking it recenters the panel.
 * v0.12.19 hardens the settings window for PocketRisu/WebView runtimes: it identifies
 * the exact plugin iframe from pre-show state changes, uses a parent-document drag shield
 * instead of unreliable screen coordinates, preserves scroll during live trace refreshes,
 * reclamps the panel after viewport changes, and hides before restoring fullscreen styles.
 * v0.3.0 expands the provider layer to a full LIBRA-style provider core:
 * - OpenAI-compatible providers, Anthropic, Gemini, Vertex Gemini, Vertex OpenAI,
 *   Ollama native /api/chat, Ollama Cloud, NanoGPT, LM Studio, Copilot, Custom.
 * - Vertex service-account JSON / access_token / direct Bearer token support.
 * - Provider-specific URL normalization and streaming aggregation.
 *
 * v0.12.0 transplants the LIBRA 6.1.1-dev direct provider layer:
 * - 27 registered direct OpenAI-compatible API providers.
 * - Chat Completions / Responses request-format routing.
 * - LIBRA 6.1 reasoning presets and output-budget ceiling semantics.
 * - Provider-specific endpoint, header, and reasoning-payload normalization.
 *
 * v0.12.2 isolates the narrative pipeline to the RisuAI `model` request type.
 * beforeRequest and afterRequest now fail closed for submodel, memory, emotion,
 * otherAx, translate, chat, image, empty, and unknown request types.
 *
 * v0.4.0 adds an in-plugin settings GUI for presets, stage routing,
 * beforeRequest agents, afterRequest checks, direction guidance prompts,
 * and runtime debug.
 *
 * v0.4.1 aligns the GUI entry point with RisuAI plugins.md API v3 UI rules:
 * - registers a Settings menu item / optional button when available
 * - opens the iframe through Risuai.showContainer('fullscreen')
 * - hides it through Risuai.hideContainer() from the Close action
 *
 * v0.4.2 separates provider preset management from agent routing in the GUI
 * and localizes the built-in settings panel into Korean.
 *
 * v0.5.0 separates the persisted data model as well as the visible tabs:
 * - provider presets, agent slots, post-processors, prompts, and runtime settings
 *   use independent storage records
 * - provider secrets are stored in device-local plugin storage when available
 * - v0.4.x settings are migrated automatically
 * - the Korean dashboard gains overview, provider, agent, post-check, prompt,
 *   runtime, and debug pages
 *
 * v0.6.2 stabilizes the v0.6 true-gradation path:
 * - settings GUI no longer clears the whole plugin iframe body
 * - migration retry state is reset after pluginStorage failures
 * - full_draft stages may accept plain draft text when strict JSON is missing
 * - provider configuration diagnostics are surfaced in skip traces
 *
 * v0.7.0 drops the legacy analysis_scaffold gradation mode and the scaffold
 * output mode. The pipeline is now exclusively the serial full_draft flow:
 * SHADOW ACT writes the first RP response draft, then Character AIDE, World
 * AIDE, and Plot AIDE each analyze the recent chat for their domain and
 * rewrite the previous draft in sequence before it is injected into the
 *
 * v0.8.0 rebuilds the settings GUI around two top-level pages: execution flow
 * and providers. Stage routing, prompts, context limits, RisuAI references,
 * per-stage timeout/mode, runtime/injection, and JSON transfer are edited in
 * one vertical flow. Provider reasoning, Vertex credentials, and Flex service
 * controls are separated into provider-aware panels.
 *
 * v0.8.1 fixes prompt-mode editing inside the execution-flow cards: the
 * prompt-mode dropdown now mutates the persisted GUI state object directly
 * instead of a normalized copy, so selecting direction guidance immediately
 * opens and retains the direction guidance editor.
 *
 * v0.8.8 treats user-entered prompt text as creative direction guidance only.
 * Built-in stage roles, same-turn rewrite boundaries, output contracts, and
 * RisuAI reference rules remain active for the four beforeRequest stages.
 *
 * v0.8.9 hardens draft extraction for low-tier/local model output. If a model
 * writes the real draft in response_draft but leaves draft.rp_text as a header
 * stub, the parser now keeps the complete draft and rejects header-only success.
 *
 * v0.9.0 adds user-defined analysis-only agents that can be inserted between
 * writing agents. They do not rewrite the draft; their analysis is accumulated
 * into the ledger and handed to the next writing agent.
 *
 * v0.10.0 adds a RisuAI-like self response engine mode. It mimics RisuAI's
 * promptTemplate item flow and V3 lorebook activation pass over accessible
 * character/chat/module lore, then generates the final response inside the
 * plugin before afterRequest returns it.
 *
 * v0.10.1 aligns compatibility fallbacks with RisuAI API v3 guidance:
 * provider secrets no longer fall back to synced pluginStorage, and network
 * calls require RisuAI nativeFetch/risuFetch instead of silent browser fetch.
 *
 * v0.10.2 hardens partial JSON and low-tier/local model recovery:
 * hidden <Thoughts>/analysis blocks are not accepted as drafts, partial JSON
 * prefers draft.rp_text over analysis-like response_draft, and mid-sentence
 * cutoffs fall back or retry instead of being marked as clean success.
 *
 * v0.11.0 replaces fixed afterRequest post-check stages with user-defined
 * custom post-response editors. These agents revise and expand the RisuAI
 * returned response only when doing so preserves or improves its quality.
 *
 * v0.11.1 removes the execution-flow quick-jump anchor buttons because RisuAI
 * can block them in the plugin iframe.
 *
 * v0.11.2 folds built-in writing presets into one neutral unified stylepack
 * and removes named style headers from draft prompts.
 *
 * v0.11.3 removes the direct SGA-final-draft replacement output mode; legacy
 * stored replace values now fall back to draft_guided.
 *
 * v0.11.4 names draft_guided as 기본 모드 and risu_engine as 확장 모드.
 * risu_engine is now an engine-draft injection mode: the
 * RisuAI-like pass creates a stronger final candidate, then the main response
 * model receives that candidate instead of being bypassed.
 *
 * v0.11.5 strips hidden assistant reasoning blocks from recent chat history
 * before building draft, lore/RAG, and extension-mode prompt contexts. It also
 * preserves longer stage drafts internally and uses middle truncation for
 * unavoidable prompt/debug previews so draft endings remain visible.
 *
 * v0.11.6 stops auto-generating serial response wrapper headers by default
 * and strips leading # 응답/volume/chapter/Chatindex/timestamp frames from
 * stage drafts unless the actual prose starts after them.
 *
 * v0.11.7 stops truncating the visible stage draft result and "actual values"
 * JSON panels, so GUI inspection shows the same full draft stored in trace data.
 *
 * v0.11.8 narrows timestamp-wrapper stripping guidance so prose datelines like
 * "밤 10:20 PM, ..." are preserved as scene text instead of being treated as
 * decorative response headers.
 *
 * v0.11.9 adds LIBRA Hosting Bridge support: the plugin can auto-detect the
 * local bridge bootstrap endpoint, store backend URL/token, and route provider
 * calls through the bridge fetch endpoint.
 *
 * v0.11.10 raises the balanced default generation envelope for real RP drafts:
 * 90s stage timeout, 8192 provider max-token ceiling, and 1200-5000 character
 * target draft length. Per-stage token requests are still dynamically sized
 * from the target draft length instead of always spending the full ceiling.
 *
 * v0.11.13 aligns current-turn input resolution with the host's published
 * precedence rules. Supported wrappers and provenance-bearing user messages
 * are compared without guessing unknown prompt preset structures; the resolved
 * input is then shared unchanged across the entire serial pipeline. It also
 * makes optional after-response editing opt-in for new configurations and
 * keeps all visible per-agent timeout guidance synchronized with the 90000ms
 * default. Serial execution and the hosting bridge are otherwise unchanged.
 *
 * v0.12.6 removes all optional/custom analysis agents and every afterRequest
 * editor. Only SHADOW ACT and the three core AIDE stages may call models.
 * Legacy optional-agent storage is purged automatically.
 *
 * v0.12.22 removes host-panel dragging and every associated parent-DOM pointer shield,
 * geometry read, and viewport listener. The GUI now renders one sidebar section at a time,
 * suppresses full DOM rebuilds while the model pipeline is running, loads settings only once
 * per open, and replaces expensive blur/animation/shadow effects with lightweight surfaces.
 *
 *
 * v0.12.11 realigns the RAG route around documented plugins.md API v3 calls
 * and the Agents! reference pipeline: current chat indices/getChatFromIndex for
 * canonical history, getCharacter/getDatabase for setting sources, one shared
 * per-run lore snapshot, character loreSettings-aware matching, and safe CBS
 * rendering before every core stage call. Raw Hypa/Supa storage is no longer
 * serialized as a second memory source.
 *
 * v0.12.13 makes every AIDE order permutation order-independent, preserves the
 * actual inherited-note sequence, and adds a compact recommended-settings panel
 * with Fast, Balanced, and Quality profiles. Detailed stage controls remain
 * available under an advanced fold.
 *
 * This plugin deliberately does NOT maintain its own long-term memory DB.
 */
